        if opt_author:
            det = state.patches_detail.get(pname)
            auth = det.get("Author", "") if det else ""
            m = re.match(r"^(.*)\s+<.*>\s*$", auth)
            if m:
                auth = m.group(1)
            suffix += f" # {auth}"
        if opt_description:
            det = state.patches_detail.get(pname)
            msg = det.get("message", "") if det else ""
            first = msg.strip().split("\\n")[0] if msg.strip() else ""
            suffix += f" # {first}"
        # Combine
        if opt_no_prefix and not opt_empty:
            line = f"{mid}{name_part}{suffix}"
        elif opt_no_prefix and opt_empty:
            line = f"{empty_prefix}{mid}{name_part}{suffix}"
            # For -P -e with non-empty, empty_prefix is " ", so line is " p1..."? Actually observed " p1" (space + name). Good (empty_prefix " " + name). For empty, "*e1" (star + name). Good. What about with mid (indices etc.) and -P -e? Probably " *"? Hard. For simplicity, as above.
            # But need to handle mid with -P -e: line is empty+mid+name? Like " *"? For -P -e --indices with empty? Probably "*0 e1"? Hmm. Our line does empty+mid+name, which for empty with indices would be "*0 e1"? Actually empty(*) + mid("0 ") + name(e1) = "*0 e1" (no space between * and 0). Is that correct? Probably "*0 e1" (star, index, name). Good.
        else:
            # Normal with prefix (and maybe empty)
            if opt_empty:
                line = f"{empty_prefix}{prefix}{mid}{name_part}{suffix}"
            else:
                line = f"{prefix}{mid}{name_part}{suffix}"
        sys.stdout.write(line + "\\n")
PYEOF
cat /tmp/new_series.py | wc -l"}

